use rand::Rng;
use std::cmp::Ordering;
use std::io;

fn main() {
    let secret = rand::rng().random_range(1..=100);
    loop {
        println!("حدس خود را وارد کنید:");
        let mut guess = String::new();
        io::stdin().read_line(&mut guess).expect("خطا در خواندن ورودی");
        let guess: u32 = match guess.trim().parse() {
            Ok(number) => number,
            Err(_) => { println!("عدد معتبر وارد کنید"); continue; }
        };
        match guess.cmp(&secret) {
            Ordering::Less => println!("کمتر است"),
            Ordering::Greater => println!("بیشتر است"),
            Ordering::Equal => { println!("درست است!"); break; }
        }
    }
}

